#!/bin/bash
# batch.sh : render every v2 Short in four sizes, finish with music, run both audits. Output in final/.
cd "$(dirname "$0")"; V=$(cd ..; pwd)
declare -A ID=([riq3khms]=listed-floral-walk-in-display-cooler-10s [rsfmh3ls]=listed-caterpillar-140h-v-plow-10s [n100s]=combi-oven-after-the-remodel-10s [n101s]=boom-lift-after-the-fitout-10s [n102s]=control-cabinet-off-the-line-10s [n103s]=drill-rig-between-contracts-10s [n104s]=vac-truck-after-the-season-10s [renr7e2s]=listed-instapak-speedypacker-floor-model-10s [r3no15xs]=listed-used-pallet-racking-complete-10s [n95s]=griddle-from-the-closed-diner-10s [n96s]=dryers-from-the-sold-laundromat-10s [n97s]=condensers-after-the-changeout-10s [n98s]=lawn-tractor-after-the-route-10s [n99s]=backhoe-still-on-the-trailer-10s [r90kwc7s]=listed-omni-metalcraft-powered-24-w-10s [n88s]=pressure-washer-the-crew-skips-10s [n89s]=mixer-after-the-pour-10s [n90s]=scissor-lift-after-the-fitout-10s [n91s]=lathe-from-the-closed-shop-10s [n92s]=flatbed-after-the-last-contract-10s [n93s]=chairs-from-the-closed-office-10s [n81s]=generator-for-the-storm-season-10s [n82s]=soldadora-en-el-carrito-10s [n83s]=read-the-plate-welder-10s [n84s]=skid-steer-after-the-grading-10s [n85s]=dump-trailer-after-the-cleanouts-10s [n86s]=cord-reels-after-the-events-10s [n87s]=wrench-wall-from-the-sold-shop-10s [n59s]=trash-pump-after-the-job-10s [n60s]=inspection-camera-in-the-van-10s [n63s]=chain-hoist-on-the-beam-10s [n69s]=lift-still-bolted-down-10s [n71s]=roller-after-the-overlay-10s [n38s]=stripped-well-pump-10s [n53s]=downsized-to-one-truck-10s [n61s]=second-jetter-by-the-fence-10s [n74s]=welder-from-one-job-10s [n75s]=compressor-by-the-fence-10s [n76s]=rooftop-unit-on-the-pallet-10s [n77s]=sprayer-after-the-season-10s [n78s]=light-tower-after-night-work-10s [n79s]=fryers-from-the-closed-kitchen-10s [n80s]=zero-turn-after-the-account-10s [n1]=ai-lists-it [n2]=find-it-nearby [n3]=free-to-list [n4]=message-the-seller [n5]=save-a-search [n6]=every-category [n7]=make-an-offer [n8]=dealer-storefront [n9]=follow-a-seller [n10]=list-4-boosted-free [n11]=already-on-craigslist [n12]=see-what-buyers-want [n14]=snap-it-list-it [n15]=spare-part [n16]=invite-a-seller [n17]=show-the-cold-start [n18]=sold-it-list-the-next [n19]=that-trailer-next-season [n20]=forklift-sitting-there [n14s]=commercial-idle-forklift [n22]=surplus-parts-cash-flow [n23]=surplus-parts-labels [n24]=micrometer-set-small-tools [n25]=boring-bars-tooling [n26]=chop-saw-small-tools [n27]=condenser-changeout [n28]=pressure-washer-replaced [n29]=air-mover-fleet [n30]=spare-truck-wheel [n31]=leftover-anchor-adhesive [n32]=part-tag-scan [n34]=parts-donor-thumb [n35]=parts-bin-lot [n36]=plumbing-part-label [n37]=leftover-fittings-lot [n38]=stripped-well-pump [n39]=control-panel-pulled [n40]=drilling-rig-parked [n41]=pressure-washer-1000-psi [n43]=building-things-concrete-mixer [n44]=bluecollar-shelf-parts [n53]=downsized-to-one-truck [n59]=trash-pump-after-the-job [n60]=inspection-camera-in-the-van [n61]=second-jetter-by-the-fence [n62]=cooler-still-humming [n63]=chain-hoist-on-the-beam [n64]=whole-lot-one-link [n65]=import-from-your-website [n66]=storefront-stats [n67]=socials-on-storefront [n68]=see-what-buyers-want-v2 [n69]=lift-still-bolted-down [n70]=box-truck-after-the-route [n71]=roller-after-the-overlay [n72]=safety-gear-on-the-wall [n74]=welder-from-one-job [n75]=compressor-by-the-fence [n76]=rooftop-unit-on-the-pallet [n77]=sprayer-after-the-season [n78]=light-tower-after-night-work [n79]=fryers-from-the-closed-kitchen [n80]=zero-turn-after-the-account)
declare -A ST=([riq3khms]=folk [rsfmh3ls]=road [n100s]=clean [n101s]=lofi [n102s]=tech [n103s]=funk [n104s]=shop [renr7e2s]=shop [r3no15xs]=folk [n95s]=clean [n96s]=lofi [n97s]=tech [n98s]=road [n99s]=funk [r90kwc7s]=folk [n88s]=road [n89s]=clean [n90s]=lofi [n91s]=tech [n92s]=funk [n93s]=shop [n81s]=road [n82s]=funk [n83s]=tech [n84s]=clean [n85s]=lofi [n86s]=shop [n87s]=folk [n59s]=clean [n60s]=folk [n63s]=lofi [n69s]=road [n71s]=folk [n38s]=funk [n53s]=road [n61s]=shop [n74s]=funk [n75s]=lofi [n76s]=road [n77s]=clean [n78s]=folk [n79s]=shop [n80s]=funk [n1]=funk [n2]=lofi [n3]=road [n4]=clean [n5]=folk [n6]=shop [n7]=funk [n8]=lofi [n9]=road [n10]=clean [n11]=folk [n12]=lift [n14]=shop [n15]=clean [n16]=funk [n17]=folk [n18]=lofi [n19]=shop [n20]=tech [n14s]=road [n22]=funk [n23]=lofi [n24]=road [n25]=clean [n26]=folk [n27]=shop [n28]=funk [n29]=lofi [n30]=road [n31]=clean [n32]=clean [n34]=folk [n35]=shop [n36]=folk [n37]=shop [n38]=funk [n39]=lofi [n40]=funk [n41]=lofi [n43]=road [n44]=clean [n53]=road [n59]=clean [n60]=folk [n61]=shop [n62]=funk [n63]=lofi [n64]=folk [n65]=shop [n66]=funk [n67]=lofi [n68]=road [n69]=road [n70]=clean [n71]=folk [n72]=shop [n74]=funk [n75]=lofi [n76]=road [n77]=clean [n78]=folk [n79]=shop [n80]=funk)
mkdir -p final/silent final/covers st
# object-matches-script check first: a spec whose opener photo or copy shows a different machine than the recording does not render
for n in "$@"; do python3 -I $V/tools/objectaudit.py r/spec/$n.json || { echo "objectaudit failed for $n, nothing rendered"; exit 1; }; done
# flat white/black borders baked into an opener photo render as slabs beside it (crop-fix thread, Nov 13): trim the source first
for n in "$@"; do python3 -I $V/tools/bordercheck.py r/spec/$n.json || { echo "bordercheck failed for $n, nothing rendered"; exit 1; }; done
for n in "$@"; do id=${ID[$n]}; st=${ST[$n]}; O=out/$n; mkdir -p $O; echo "== $n $id $st $(date +%H:%M:%S)"
  node renderspec.js r/spec/$n.json 1080 1920 $O/9x16.mp4 >$O/9x16.log 2>&1 &
  node renderspec.js r/spec/$n.json 1080 1350 $O/4x5.mp4  >$O/4x5.log 2>&1 &
  wait  # Nov 18: two renders at a time (four at once crashed the compositor twice)
  node renderspec.js r/spec/$n.json 1080 1080 $O/1x1.mp4  >$O/1x1.log 2>&1 &
  node renderspec.js r/spec/$n.json 1920 1080 $O/16x9.mp4 >$O/16x9.log 2>&1 &
  wait; grep -h "ERROR\|CONSOLE" $O/*.log
  grep -q OVERLAP $O/*.log && { echo "TEXT OVERLAP in $n, nothing deployed for $n"; grep -h OVERLAP $O/*.log | head -5; exit 1; }
  for s in 9x16 4x5 1x1 16x9; do grep -q "^done " $O/$s.log || { echo "RENDER FAILED $n $s (see $O/$s.log), nothing deployed for $n"; tail -3 $O/$s.log; exit 1; }; done
  for s in 9x16 4x5 1x1 16x9; do python3 -I finish.py $O/$s.mp4 $O/fin-$s.mp4 $st >$O/fin-$s.log 2>&1 & done; wait
  for s in 9x16 4x5 1x1; do mv $O/fin-$s.mp4 final/yardswaps-$id-$s.mp4; mv $O/fin-$s-silent.mp4 final/silent/yardswaps-$id-$s.mp4; mv $O/fin-$s-cover.jpg final/covers/yardswaps-$id-$s.jpg; done
  mv $O/fin-16x9.mp4 final/yardswaps-$id-16x9-music.mp4; mv $O/fin-16x9-silent.mp4 final/yardswaps-$id-16x9.mp4; mv $O/fin-16x9-cover.jpg final/covers/yardswaps-$id-16x9.jpg
  python3 -I $V/tools/cropaudit.py final/yardswaps-$id-9x16.mp4 final/yardswaps-$id-4x5.mp4 final/yardswaps-$id-1x1.mp4 final/yardswaps-$id-16x9-music.mp4 2>&1 | sed "s/^/crop /"
  python3 -I $V/tools/audioaudit.py final/yardswaps-$id-9x16.mp4 final/yardswaps-$id-4x5.mp4 final/yardswaps-$id-1x1.mp4 final/yardswaps-$id-16x9-music.mp4 | sed "s/^/audio /"
  ffmpeg -v error -y -i final/yardswaps-$id-9x16.mp4 -vf "fps=1/2,scale=-2:480,tile=6x2" st/$n-9x16.jpg
  ffmpeg -v error -y -i final/yardswaps-$id-16x9-music.mp4 -vf "fps=1/2,scale=-2:300,tile=4x3" st/$n-16x9.jpg
  rm -f $O/*.mp4
done; echo "== batch done $(date +%H:%M:%S)"
